% % PAL_tr.SSA111=[];

%compute trend on G
PAL_tr.BsB_S11=[];
PAL_tr.BsR_S11=[];
PAL_tr.BbsB_S11=[];
PAL_tr.BbsR_S11=[];
%only expS bg
PAL_tr.expS_br3=[];
PAL_tr.expS_gr3=[];
%%
PAL_result= all_trend_STN(PAL_tr,PAL_st); 
plot_10y_in_two(PAL_result, PAL_st);
